/**
 * 创建一个安全的异步函数，多次连续调用，保证响应的结果是最后一次调用的
 *
 * @example
 * const safeFetcher = safeRace(fetcher);
 *
 */
export function safeRace(fetcher: any, { onDiscardedPromiseError, enabled }?: {
    onDiscardedPromiseError: any;
    enabled?: boolean;
}): any;
export function useSafeRace(fn: any, safeRaceOptions?: {}): any;
